// PLANTILLA de fantasia: sustituye este marcador por tu escena 3D.
// Gestos: smileStart, oMouth. Sonido: window.folio.sfx.play("fantasia")
var k = 0;
function init() { this.scale.setScalar(1); }
function smileStart() { k = 1; window.folio?.sfx.play("fantasia"); }
function oMouth() { k = 1; window.folio?.sfx.play("pop"); }
function update(event) { k = Math.max(0, k - event.delta / 700); this.scale.setScalar(1 + k * 1.5); this.rotation.y += event.delta / 800; }
